        From 18cc39bd92ed97a36d96fb505b90b2886387d6c3 Mon Sep 17 00:00:00 2001
From: Claudio Takahasi <ckt@cesar.org.br>
Date: Thu, 11 Apr 2019 15:57:25 -0300
Subject: [PATCH] Fix accessing invalid memory address

This patch fixes a bug introduced by 03ffbdd338937045f8b2edde0d440eb57b52a127.
String passed to message builder should not be released before
sending the message.
---
 src/slave.c | 7 +++----
 1 file changed, 3 insertions(+), 4 deletions(-)

diff --git a/src/slave.c b/src/slave.c
index 3285164..0828ed8 100644
--- a/src/slave.c
+++ b/src/slave.c
@@ -42,6 +42,7 @@ struct slave {
 	bool enable;
 	char *name;
 	char *path;
+	char *ipaddress;
 	char *hostname;
 	char *port; /* getaddrinfo service */
 	modbus_t *tcp;
@@ -93,6 +94,7 @@ static void slave_free(struct slave *slave)
 	}
 	storage_close(slave->sources_fd);
 	l_free(slave->key);
+	l_free(slave->ipaddress);
 	l_free(slave->hostname);
 	l_free(slave->port);
 	l_free(slave->name);
@@ -441,12 +443,9 @@ static bool property_get_ipaddress(struct l_dbus *dbus,
 				  void *user_data)
 {
 	struct slave *slave = user_data;
-	char *address = l_strdup_printf("%s:%s", slave->hostname, slave->port);

 	/* PLC/Peer IP address */
-	l_dbus_message_builder_append_basic(builder, 's', &address);
-
-	l_free(address);
+	l_dbus_message_builder_append_basic(builder, 's', &slave->ipaddress);

 	return true;
 }
-- 
